package cn.local.rainreminder;
import android.content.Context;import android.view.View;import android.widget.RemoteViews;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.Locale;
final class WidgetDateNav {
 static void bind(Context c,RemoteViews views,int id,boolean week,boolean secondary,long now){int bar=secondary?R.id.widget_secondary_nav:R.id.widget_day_nav,previous=secondary?R.id.widget_secondary_nav_previous:R.id.widget_day_previous,next=secondary?R.id.widget_secondary_nav_next:R.id.widget_day_next,today=secondary?R.id.widget_secondary_nav_today:R.id.widget_day_today,title=secondary?R.id.widget_secondary_nav_title:R.id.widget_day_title;LocalDate day=WidgetOptions.date(c,id,now),monday=day.minusDays(day.getDayOfWeek().getValue()-1);views.setViewVisibility(bar,View.VISIBLE);views.setTextViewText(title,week?monday.format(DateTimeFormatter.ofPattern("M.d"))+"—"+monday.plusDays(6).format(DateTimeFormatter.ofPattern("M.d")):day.format(DateTimeFormatter.ofPattern("M月d日 E",Locale.CHINA)));views.setTextViewText(today,week?"本周":"今天");views.setOnClickPendingIntent(previous,WidgetDayTable.navigation(c,id,week?-7:-1));views.setOnClickPendingIntent(next,WidgetDayTable.navigation(c,id,week?7:1));views.setOnClickPendingIntent(today,WidgetDayTable.navigation(c,id,0));views.setContentDescription(previous,week?"上一周":"前一天");views.setContentDescription(next,week?"下一周":"后一天");views.setContentDescription(today,week?"返回本周":"返回今天");}
}
